private Map<String, Double> validateScores(Map<String, Double> raw) {
    Map<String,Double> result = new HashMap<>();
    for (String key : VALID_EMOTIONS) {
        result.put(key, Math.max(0.0, Math.min(1.0, raw.getOrDefault(key, 0.0))));
    }
    return result;
}

private String extractJsonText(String text) {
    if (text == null) return "{}";
    text = text.trim();
    if (text.startsWith("```")) {
        text = text.replaceAll("^```(?:json)?\\n?", "").replaceAll("\\n?```$", "");
    }
    return text;
}
